private void btn_valider_Click(object sender, EventArgs e)
        {
            try 
            {
                CnxBase cnxbase = new CnxBase();
                bool medObligatoire = false;
                int resultComparedate = DateTime.Compare(Convert.ToDateTime(DateTime.Parse(Tx_DteRDV.Text).ToShortDateString() + " " + DateTime.Parse(Tx_HeureRdv.Text).ToShortTimeString()), DateTime.Now);
                if (resultComparedate < 0 && (Mode == "ajout"))
                {
                    MessageBox.Show("Impossible d'ajouter un rdv à une date antérieure", "Erreur", MessageBoxButtons.OK, MessageBoxIcon.Information);
                    Tx_DteRDV.Focus();
                    return;

                }
                for (int i = 0; i < rdvs.Rows.Count; i++)
                {
                    string codeEx = rdvs.Rows[i][0].ToString();
                    bool existe = EXAMRAD.getInstance().etatMedecin(codeEx);
                    if (existe)
                        medObligatoire = true;
                }
                if (DateTime.Parse(Tx_DteRDV.Text).Year < 1900)
                {
                    MessageBox.Show("Date invalide", "Erreur", MessageBoxButtons.OK, MessageBoxIcon.Information);
                    Tx_DteRDV.Focus();
                    return;
                }

                DateTime testdate = DateTime.MinValue;

                //01/01/0001 00:00:00
                if (!DateTime.TryParse(txt_duree.Text, out testdate))
                {
                    txt_duree.Select();
                    MessageBox.Show("Saisir la durée");
                    return;
                }
                DateTime datecompare = DateTime.MinValue.AddMinutes(6);
                int resultCompareduree = TimeSpan.Compare( testdate.TimeOfDay,datecompare.TimeOfDay);

                if (resultCompareduree < 0)
                {
                    txt_duree.Select();
                    MessageBox.Show("La durée doit être supérieure à 00:06");
                    return;
                }
                if (Tx_Age.Text.Length == 10)
                {
                    if (int.Parse(Tx_Age.Text.Substring(6, 4)) > 1800)
                    {
                        if (int.Parse(Tx_Age.Text.Substring(3, 2)) < 12)
                        {
                            if (int.Parse(Tx_Age.Text.Substring(3, 2)) == 2 && int.Parse(Tx_Age.Text.Substring(0, 2)) > 29)
                            {
                                MessageBox.Show("Date invalide", "Erreur", MessageBoxButtons.OK, MessageBoxIcon.Information);
                                Tx_Age.Focus();
                                return;
                            }
                            if (DateTime.Parse(Tx_Age.Text).Year < 1900 || DateTime.Parse(Tx_Age.Text).Year > DateTime.Today.Year)
                            {

                                MessageBox.Show("Date invalide", "Erreur", MessageBoxButtons.OK, MessageBoxIcon.Information);
                                Tx_Age.Focus();
                                return;
                            }
                        }
                    }
                    else
                    {
                        MessageBox.Show("Date invalide", "Erreur", MessageBoxButtons.OK, MessageBoxIcon.Information);
                        Tx_Age.Focus();
                        return;
                    }
                }
                else if (Tx_Age.Text == "  /  /")
                {
                    //  break  ;
                }
                else
                {
                    MessageBox.Show("Date invalide", "Erreur", MessageBoxButtons.OK, MessageBoxIcon.Information);
                    Tx_Age.Focus();
                    return;
                }

                if (Tx_Age.Text.Length == 10)
                {
                    if (int.Parse(Tx_Age.Text.Substring(3, 2)) > 12)
                    {
                        MessageBox.Show("Date invalide", "Erreur", MessageBoxButtons.OK, MessageBoxIcon.Information);
                        Tx_Age.Focus();
                        return;

                    }

                }
                if (!planningpasalle && Tx_codmed.SelectedValue == null)
                {
                    Tx_codmed.Select();
                    MessageBox.Show("Spécifier le médecin", "Erreur", MessageBoxButtons.OK, MessageBoxIcon.Information);
                    return;
                }
                if (medObligatoire && Tx_codmed.Text == string.Empty)
                {
                    MessageBox.Show("Spécifier le médecin", "Erreur", MessageBoxButtons.OK, MessageBoxIcon.Information);
                    return;
                }

                if (medObligatoire && Tx_codmed.Text != string.Empty)
                {
                    string nbMedeDisponible = RDV.getInstance().GetEtatMedecinHeureDate(Tx_codmed.SelectedValue.ToString(), Tx_DteRDV.Text, Tx_HeureRdv.Text);
                    if (int.Parse(nbMedeDisponible) > 0)
                    {
                        MessageBox.Show("Médecin indisponible pendant l'horaire choisi", "Erreur", MessageBoxButtons.OK, MessageBoxIcon.Information);
                        return;
                    }
                }

                if (Tx_Prenom.Text == "")
                {
                    MessageBox.Show("Spécifier le prénom", "Erreur", MessageBoxButtons.OK, MessageBoxIcon.Information);
                    return;
                }
                if (Tx_Nom.Text == "")
                {
                    MessageBox.Show("Spécifier le nom", "Erreur", MessageBoxButtons.OK, MessageBoxIcon.Information);
                    return;
                }
                if (rdvs.Rows.Count == 0)
                {
                    MessageBox.Show("Spécifier l'examen", "Erreur", MessageBoxButtons.OK, MessageBoxIcon.Information);
                    return;
                }
                if (CnxBase.Tel_Fix)
                {
                    if (string.IsNullOrEmpty(Tx_TelFix.Text))
                    {
                        MessageBox.Show("Spécifier le numéro du téléphone", "Erreur", MessageBoxButtons.OK, MessageBoxIcon.Information);
                        Tx_TelFix.Select();
                        return;
                    }
                }
                if (Tx_DteRDV.Text == "")
                {
                    MessageBox.Show("Spécifier la date du rendez Vous", "Erreur", MessageBoxButtons.OK, MessageBoxIcon.Information);
                    return;
                }
                if (Tx_HeureRdv.Text == "")
                {
                    MessageBox.Show("Spécifier l'heure du rendez Vous", "Erreur", MessageBoxButtons.OK, MessageBoxIcon.Information);
                    return;
                }
                DateTime t = DateTime.Parse(debut.ToShortDateString());

                DateTime dtSys = DateTime.Parse(Base_Function.getInstance().GetDate(CnxBase.myConn).ToShortDateString());

                DateTime datTemp = DateTime.Parse(dtSys.ToShortDateString());
                DateTime HeureRdv = DateTime.Parse("01/01/2000 " + Tx_HeureRdv.Text);
                //if (Tx_codmed.SelectedValue != null && !detailsIndispoMed.getInstance().verifDisponibiliteMedecin(Tx_codmed.SelectedValue.ToString(), HeureRdv, HeureRdv, Convert.ToDateTime(Tx_DteRDV.Text)))
                //{
                //    MessageBox.Show("Médecin indisponible pendant l'horaire choisi", "Erreur", MessageBoxButtons.OK, MessageBoxIcon.Information);
                //    return;
                //}


                //if (!planningpasalle)
                //{
                //    if (!ValiderRdv()) return;
                //}
                #region Controle de disponibilité du centre
                DataTable dtIndisp = RDV.getInstance().GetRdvsIndispo_centre(DateTime.Parse(Tx_DteRDV.Text), HeureRdv, _codeCentre, _codSalle);
                if (dtIndisp.Rows.Count > 0)
                {
                    string chMessage = string.Empty;
                    foreach (DataRow dr in dtIndisp.Rows)
                    {
                        string codeTypeIndisp = dr[0].ToString();


                        if (codeTypeIndisp == "02")   // INDISPONIBILITE ABSOLUE
                        {
                            chMessage += dr[1].ToString() + " \n";
                        }
                        else if (codeTypeIndisp == "01" && DateTime.Parse(dtSys.ToShortDateString()) != DateTime.Parse(Tx_DteRDV.Text))
                        {
                            DateTime debIndisp = Convert.ToDateTime(dr["Heure_Debut"]);
                            DateTime finIndisp = Convert.ToDateTime(dr["Heure_Fin"]);
                            TimeSpan tsIndisp = finIndisp - debIndisp;
                            double nbMinute = tsIndisp.TotalMinutes;
                            double nbCartHeure = nbMinute / 15;
                            TimeSpan tsOx = (finIndisp - HeureRdv);
                            double RONG = nbCartHeure - (tsOx.TotalMinutes / 15);
                            if (RONG % 2 != 0)
                            {
                                chMessage += dr[1].ToString() + " \n";
                            }
                        }
                        else if (codeTypeIndisp == "03" && DateTime.Parse(dtSys.ToShortDateString()) != DateTime.Parse(Tx_DteRDV.Text))
                        {
                            chMessage += dr[1].ToString() + " \n";
                        }
                        else if (codeTypeIndisp == "04")
                        {
                            dtSys = DateTime.Parse(Base_Function.getInstance().GetTime1(CnxBase.myConn));
                            DateTime debDsip = DateTime.Parse(DateTime.Parse(Tx_DteRDV.Text).AddDays(-1).ToShortDateString() + " " + dr["heureDesbdisp"].ToString());
                            if (dtSys < debDsip)
                            {
                                chMessage += dr[1].ToString() + " \n";
                            }

                        }
                    }

                    if (chMessage != string.Empty)
                    {
                        MessageBox.Show(" Centre non disponible\n Nature indisponibilité " + chMessage, "Clinisys", MessageBoxButtons.OK, MessageBoxIcon.Information);
                        return;
                    }
                }
                #endregion


                if (Mode == "ajout")

                {
                    lb_titre.Text = "Ajout d'un rendez-vous".ToUpper();
                    string s = DateTime.Parse(Tx_DteRDV.Text).ToShortDateString() + " " + DateTime.Parse(Tx_HeureRdv.Text).ToShortTimeString();
                    DateTime HeureDebutRdv = Convert.ToDateTime(s);
                    TimeSpan tsdurees = new System.TimeSpan(Convert.ToDateTime(txt_duree.Text).Ticks);
                    //string HeureFinRdv = Convert.ToDateTime(HeureDebutRdv).Add(tsdurees).ToShortTimeString();
                    //if (!RDV.getInstance().getRdvDisponible(Convert.ToDateTime(HeureDebutRdv), Convert.ToDateTime(HeureFinRdv).AddMinutes(-1), "", _codSalle))




                    DateTime heureFin = Convert.ToDateTime(HeureDebutRdv.ToShortDateString() + " " + Convert.ToDateTime(HeureDebutRdv).Add(tsdurees).ToShortTimeString());
                  //  if (!RDV.getInstance().getRdvDisponible(Convert.ToDateTime(HeureDebutRdv), Convert.ToDateTime(heureFin).AddMinutes(-1), num_rdv, _codSalle) && planningpasalle)
                    if (!RDV.getInstance().getRdvDisponible(Convert.ToDateTime(HeureDebutRdv), Convert.ToDateTime(heureFin).AddMinutes(-1),"", _codSalle) && planningpasalle) 
                    {
                        MessageBox.Show("Salle non disponible à cet horaire", "Erreur", MessageBoxButtons.OK, MessageBoxIcon.Information);
                        return;
                    }
                    if (!planningpasalle)
                    {
                        //if (!(RDV.getInstance().getRdvDisponibleByCoodeMed(Convert.ToDateTime(HeureDebutRdv), Convert.ToDateTime(heureFin).AddMinutes(-1), num_rdv, Tx_codmed.SelectedValue.ToString())))
                        if (!(RDV.getInstance().getRdvDisponibleByCoodeMed(Convert.ToDateTime(HeureDebutRdv), Convert.ToDateTime(heureFin).AddMinutes(-1), "", Tx_codmed.SelectedValue.ToString())))
                        {
                            MessageBox.Show("Médecin non disponible à cet horaire", "Erreur", MessageBoxButtons.OK, MessageBoxIcon.Information);
                            return;
                        }
                    }
                    this .validAuthentif =false ; 
                    Frm_Authentifa f = new Frm_Authentifa(this ,"rdv");
                    f.ShowDialog();
                    if (!this .validAuthentif )
                    {
                        return;
                    }
                    cnxbase = new CnxBase();
                    #region ModeAjout
                    rdvs.AcceptChanges();
                    Centre ctxy = new Centre();
                    ctxy.Code_Centre = _codeCentre;
                    Centre.getInstance().obtenirInstanceCentre(ctxy);
                    DataTable dtforgrid = new DataTable();
                    DataTable dt = new DataTable();
                    dt = RDV.getInstance().GetListRDVToCheck("Code_Centre = '" + _codeCentre + "'");
                    RDV rdv = new RDV();

                    string examen = string.Empty;
                    DateTime dtime = DateTime.Parse(Tx_DteRDV.Text);
                    string listExam = string.Empty;
                    for (int i = 0; i < rdvs.Rows.Count; i++)
                    {
                        listExam += string.Format(",'{0}'", rdvs.Rows[i][0].ToString());
                        examen+= rdvs.Rows[i][1].ToString()+" , ";
                    }
                    if (listExam != string.Empty)
                    {
                        listExam = listExam.Substring(1);
                    }
                    if (examen != string.Empty)
                        examen.Remove(examen.Length - 2);
                    DateTime dateregister = Base_Function.getInstance().GetDate(CnxBase.myConn);
                    Boolean err = false;
                    CnxBase.trans = CnxBase.myConn.BeginTransaction(IsolationLevel.Serializable);
                    try
                    {
                        if (_natureActe == "30")
                        {
                            DataTable dtBlocagecontrole = Centre.getInstance().GetBlocagecontrole(_codeCentre);
                         if (dtBlocagecontrole.Rows[0][0].ToString() == "True")
                         {
                             DataTable dtVerifExistRdv = RDV.getInstance().VerifExistRdv(txt_identifiant.Text, _codeCentre, Convert.ToDateTime(DateTime.Parse(Tx_DteRDV.Text).ToShortDateString()));
                             if (dtVerifExistRdv.Rows.Count != 0)
                             {
                                 throw (new Exception("Ce patient a déjà un RDV à cette date ", new Exception("CliniSys Erp")));
                             }
                         }

                        }
                        rdv.examen = examen.Replace("'", "''"); ;
                        rdv.Date_nais = Tx_Age.Text == "  /  /" ? DateTime.Parse("01/01/1900") : DateTime.Parse(Tx_Age.Text);
                        rdv.Objet = Tx_objet.Text;
                        rdv.Anesthesie = Ch_AG.Checked == false ? 0 : 1;
                        rdv.Code_Examen = "";
                        rdv.Date_Cre = dateregister;
                        rdv.Date_RDV = DateTime.Parse(Tx_DteRDV.Text);
                        rdv.Heure_RDV = DateTime.Parse("01/01/2000 " + Tx_HeureRdv.Text);
                        rdv.Nom = Tx_Nom.Text.Replace("'", "''");
                        rdv.Prenom = Tx_Prenom.Text.Replace("'", "''");
                        rdv.User_Cre = CnxBase.login;
                        rdv.Duree = DateTime.Parse(txt_duree.Text).AddMinutes(-1);
                        rdv.valide = false;
                        rdv.Code_Centre = _codeCentre;
                        rdv.Email = Tx_Email.Text.Replace("'", "''");
                        rdv.Fax = Tx_Fax.Text.Replace("'", "''");
                        rdv.Tel_Fixe = Tx_TelFix.Text.Replace("'", "''");
                        rdv.Tel_Port = Tx_Portable.Text.Replace("'", "''");
                        //rdv.Regime = "";// Tx_Regime.Text;
                        if (Tx_Prescripteur.SelectedValue != null)
                            rdv.Code_MedecinPrescripteur = Tx_Prescripteur.SelectedValue.ToString();
                        else
                            rdv.Code_MedecinPrescripteur = "";

                        if (RDV.getInstance().GetMaxCodeRDV() != "")
                            rdv.Num_RDV = "R" + SerialiserNumRDV(int.Parse(RDV.getInstance().GetMaxCodeRDV()) + 1);
                        else

                            rdv.Num_RDV = "R000000001";
                        //if (rdv.GetNumDoss(rdv.Num_RDV).Rows.Count > 0)
                        //{
                        //    if (RDV.getInstance().GetMaxCodeRDV() != "")
                        //        rdv.Num_RDV = "R" + SerialiserNumRDV(int.Parse(RDV.getInstance().GetMaxCodeRDV()) + 1);
                        //    else
                        //        rdv.Num_RDV = "R000000001";
                        //}

                        if (!planningpasalle)
                            rdv.CodeSalle = String.Empty;
                        else
                            rdv.CodeSalle = _codSalle;

                        if (Tx_codmed.SelectedValue != null)
                            rdv.CodeMed = Tx_codmed.SelectedValue.ToString();//Tx_codmed.Text.Replace("'", "''");
                        else
                            rdv.CodeMed = "";

                        rdv.Confirme = chConfirme.Checked;
                        if (chConfirme.Checked)
                        {
                            rdv.UserConfirme = CnxBase.login;
                            rdv.DateConfirme = dateregister;
                        }
                        //R160014424
                        while (RDV.getInstance().GetExisteRDV(rdv.Num_RDV) == rdv.Num_RDV)
                        {
                            rdv.Num_RDV = "R" + SerialiserNumRDV(int.Parse(RDV.getInstance().GetMaxCodeRDV()) + 1);
                        }

                        if (CnxBase.Facturation)
                        {
                            rdv.Observation = txtObservation.Text.Replace("'","''");
                        }




                        rdv.NumCIN=Tx_Piece.Text.Replace("'","''"); 
                        rdv.AdrCli=Tx_Adr.Text.Replace("'","''"); 



                        rdv.ajouteRDVSSADM(rdv);
                        Examen_Rdv exman = new Examen_Rdv();
                        for (int i = 0; i < rdvs.Rows.Count; i++)
                        {
                            exman.Num_RDV = rdv.Num_RDV;
                            exman.Code_examen = rdvs.Rows[i][0].ToString();
                            exman.ajouteExamen_Rdv(exman);
                        }
                        if (txt_identifiant.Text != string.Empty)
                            rdv.UPDATEidentifiantRDV(rdv.Num_RDV, txt_identifiant.Text);





                        //Ajout dmndeDossier
                        if (_natureActe == "30" )
                        {
                            DemandeDossier myDmnde = new DemandeDossier();
                            myDmnde.numDmnde = Param.getInstance().getParamByCode("DmndeDossier");
                            myDmnde.identifiant = txt_identifiant.Text;
                            myDmnde.userDmnde = CnxBase.login;
                            myDmnde.dateDmnde = CnxBase.getDate();
                            myDmnde.datePrevueLiv = DateTime.Parse(Tx_DteRDV.Text);
                            myDmnde.EmplacementLiv = Centre.getInstance().getCodeEmplLiv(_codeCentre); 
                            myDmnde.etatLiv = 0;
                            myDmnde.userLiv = string.Empty;
                            myDmnde.dateLiv = Convert.ToDateTime("01/01/1900");
                            if(Tx_codmed.SelectedValue!=null)
                            myDmnde.Observation = Medecin.getInstance().getNomByCode(Tx_codmed.SelectedValue.ToString());
                            myDmnde.ajouteDemandeDossier(myDmnde);


                            //update compteur
                            Int64 cmpt = Convert.ToInt64(myDmnde.numDmnde) + 1;
                            Param myparam = new Param();
                            myparam.modifierParam(cmpt.ToString(), "DmndeDossier");

                        }


                        CnxBase.trans.Commit();
                    }
                    catch (Exception ex)
                    {
                        err = true;
                        CnxBase.trans.Rollback();
                        MessageBox.Show(ex.Message.ToString(), "CliniSyS", MessageBoxButtons.OK, MessageBoxIcon.Error);
                    }
                    if (!err)
                    {
                        myForm1.LoadData("RDV.Code_Centre = '" + _codeCentre + "' and RDV.date_rdv = '" + debut.ToShortDateString() + "'", 0);
                        this.Close();
                    } 
                    #endregion


                }
                else
                {

                    if (Mode == "modification")
                    {
                        lb_titre.Text = "modification du rendez-vous".ToUpper();
                        if (debut.ToShortDateString() != Tx_DteRDV.Text)
                        {
                            int resultComparedate2 = DateTime.Compare(Convert.ToDateTime(DateTime.Parse(Tx_DteRDV.Text).ToShortDateString() + " " + DateTime.Parse(Tx_HeureRdv.Text).ToShortTimeString()), DateTime.Now);
                            if (resultComparedate2 < 0)
                            {
                                MessageBox.Show("Impossible de modifier un rdv à une date antérieure", "Erreur", MessageBoxButtons.OK, MessageBoxIcon.Information);
                                Tx_DteRDV.Value = Tx_DteRDV.Text = debut.ToShortDateString();
                                Tx_DteRDV.Focus();
                                return;
                            }
                        }

                        string s = DateTime.Parse(Tx_DteRDV.Text).ToShortDateString() + " " + DateTime.Parse(Tx_HeureRdv.Text).ToShortTimeString();
                        DateTime HeureDebutRdv = Convert.ToDateTime(s);
                        TimeSpan tsdurees = new System.TimeSpan(Convert.ToDateTime(txt_duree.Text).Ticks);
                       // string HeureFinRdv = Convert.ToDateTime(HeureDebutRdv).Add(tsdurees).ToShortTimeString();
                        DateTime heureFin = Convert.ToDateTime(HeureDebutRdv.ToShortDateString() + " " + Convert.ToDateTime(HeureDebutRdv).Add(tsdurees).ToShortTimeString());
                        if (!RDV.getInstance().getRdvDisponible(Convert.ToDateTime(HeureDebutRdv), Convert.ToDateTime(heureFin).AddMinutes(-1), num_rdv, _codSalle))

                        if (!RDV.getInstance().getRdvDisponible(Convert.ToDateTime(HeureDebutRdv), Convert.ToDateTime(heureFin).AddMinutes(-1), num_rdv, _codSalle)&& planningpasalle)
                        {
                            MessageBox.Show("Salle non disponible à cet horaire", "Erreur", MessageBoxButtons.OK, MessageBoxIcon.Information);
                            return;
                        }
                        Boolean err = false;

                        //string condition = " WHERE( Num_RDV='" + num_rdv + "' and date_rdv='" + DateTime.Parse(debut.ToShortDateString()).ToString() + "' and heure_rdv ='" + DateTime.Parse("01/01/2000 " + debut.ToShortTimeString()).ToString() + "')";

                        string condition = " WHERE( Num_RDV='" + num_rdv + "' )";
                        DateTime dtime = DateTime.Parse(Tx_DteRDV.Text);
                        DataTable dt = new DataTable();
                        if(!string.IsNullOrEmpty(numdoss))
                            dt = RDV.getInstance().GetRDVSByDateTimeClient(dtime.ToShortDateString(), "01/01/2000 " + Tx_HeureRdv.Text, numdoss);
                        if (dt.Rows.Count > 0)
                        {
                            RDV test = new RDV();
                            test.Num_RDV = num_rdv;
                            test = test.obtenirInstanceDateHeureRDVByNumRDV(test);
                            if (test.NumDoss != numdoss)
                            {
                                MessageBox.Show("Ce patient a déjà un rendez-vous à cette date et à cette heure");
                                return;
                            }
                            else
                            {
                                if (test.Date_RDV != DateTime.Parse(Tx_DteRDV.Text) || test.Heure_RDV != DateTime.Parse("01/01/2000 " + Tx_HeureRdv.Text))
                                {
                                    MessageBox.Show("Ce patient a déjà un rendez-vous à cette date et à cette heure", "Erreur", MessageBoxButtons.OK, MessageBoxIcon.Stop);
                                    return;
                                }
                            }

                        }
                        this.validAuthentif = false;
                        Frm_Authentifa f = new Frm_Authentifa(this, "rdv");
                        f.ShowDialog();
                        if (!this.validAuthentif)
                        {
                            return;
                        }
                        cnxbase = new CnxBase();

                        string examen = string.Empty;
                        CnxBase.trans = CnxBase.myConn.BeginTransaction(IsolationLevel.Serializable);
                        try
                        {
                            #region ModeModification
                            dt = RDV.getInstance().GetListRDVToCheck("Code_Centre = '" + _codeCentre + "'");
                            DataTable rdvDatatable = RDV.getInstance().GetRdvByID(condition);

                            //for (int i = 0; i < rdvs.Rows.Count; i++)
                            //{
                            //    examen += rdvs.Rows[i][1].ToString() + " , ";
                            //}
                            string examenModif = string.Empty;
                            string listExam = string.Empty;
                            for (int i = 0; i < rdvs.Rows.Count; i++)
                            {
                                examenModif += rdvs.Rows[i][1].ToString() + " ,";
                            }
                            if (examenModif != string.Empty)
                                examenModif=examenModif.Remove(examenModif.Length - 2);
                            RDV r1 = new RDV();
                            r1.examen = examenModif.Replace("'", "''"); ;
                            r1.Num_RDV = num_rdv;
                            r1.Date_nais = Tx_Age.Text == "  /  /" ? DateTime.Parse("01/01/1900") : DateTime.Parse(Tx_Age.Text);
                            r1.Objet = Tx_objet.Text.Replace("'", "''");
                            r1.Anesthesie = Ch_AG.Checked == false ? 0 : 1; ;
                            r1.Code_Examen = "";
                            r1.Date_RDV = DateTime.Parse(Tx_DteRDV.Text);
                            r1.Heure_RDV = DateTime.Parse("01/01/2000 " + Tx_HeureRdv.Text);
                            r1.Duree = DateTime.Parse(txt_duree.Text).AddMinutes(-1);
                            r1.Nom = Tx_Nom.Text.Replace("'", "''");
                            r1.Prenom = Tx_Prenom.Text.Replace("'", "''");
                            // update rdv identifiant
                            r1.identifiant = txt_identifiant.Text.Replace("'", "''");
                            r1.valide = false;
                            r1.Code_Centre = rdvDatatable.Rows[0]["Code_Centre"].ToString();
                            r1.Numdemande = rdvDatatable.Rows[0]["Numdemande"].ToString();
