                            r1.NumDoss = rdvDatatable.Rows[0]["NumDoss"].ToString();
                            r1.Email = Tx_Email.Text.Replace("'", "''");
                            r1.Fax = Tx_Fax.Text.Replace("'", "''");
                            if (Tx_NumSoc.Text != string.Empty)
                                r1.Num_Soc = Tx_NumSoc.SelectedValue.ToString();
                            r1.Tel_Fixe = Tx_TelFix.Text.Replace("'", "''");
                            r1.Tel_Port = Tx_Portable.Text.Replace("'", "''");
                            r1.Code_Machine = "";
                            r1.Code_Tech = "";
                            if (Tx_codmed.SelectedValue != null)
                                r1.CodeMed = Tx_codmed.SelectedValue.ToString(); //txt_codemed.Text.Replace("'", "''");
                            else
                                r1.CodeMed = "";
                            if (Tx_Prescripteur.SelectedValue != null)
                                r1.Code_MedecinPrescripteur = Tx_Prescripteur.SelectedValue.ToString();
                            else
                                r1.Code_MedecinPrescripteur = "";
                            if (CnxBase.Facturation)
                            {
                                r1.Observation = txtObservation.Text.Replace("'", "''");
