ctx.fillStyle = 'rgba(255, 255, 255, ' + 0.1 + ')';
ctx.fill();
}

// Draw radial grid
drawRadialGrid();

// Draw the Sun
const sunPos2D = projectTo2D(sunPos.x, sunPos.y, sunPos.z);
drawPlanet(sunPos2D.x, sunPos2D.y, sunPos.size, '#ffcc00');

// Draw Mercury
const mercPos2D = projectTo2D(mercuryPos.x - sunPos.x, mercuryPos.y - sunPos.y, mercuryPos.z - sunPos.z);
drawPlanet(mercPos2D.x, mercPos2D.y, mercuryPos.size, '#ff6666');

// Draw Venus
const venusPos2D = projectTo2D(venusPos.x - sunPos.x, venusPos.y - sunPos.y, venusPos.z - sunPos.z);
drawPlanet(venusPos2D.x, venusPos2D.y, venusPos.size, '#ffa500');

// Draw Earth
const earthPos2D = projectTo2D(earthPos.x - sunPos.x, earthPos.y - sunPos.y, earthPos.z - sunPos.z);
drawPlanet(earthPos2D.x, earthPos2D.y, earthPos.size, '#6699ff');

// Update planet positions for the next frame
updatePlanetPositions();

// Update rotation angles based on mouse position
let isDragging = false;
let initialMousePos = { x: 0, y: 0 }; // store initial mouse position when dragging starts
let currentRotation = { x: rotation.x, y: rotation.y }; // initialize current rotation angles to the current rotation
let prevRotation = { x: 0, y: 0 }; // store previous (last) rotation angles

canvas.addEventListener('mousedown', function (event) {
isDragging = true;
initialMousePos.x = event.clientX;
initialMousePos.y = event.clientY;
prevRotation.x = currentRotation.x; // store previous rotation angles
prevRotation.y = currentRotation.y;
});

canvas.addEventListener('mouseup', function (event) {
isDragging = false;
});

canvas.addEventListener('mousemove', function (event) {
if (isDragging) {
// calculate new rotation angles based on difference between current mouse position and initial mouse position
currentRotation.x = prevRotation.x + (event.clientY - initialMousePos.y) / canvas.height * Math.PI;
currentRotation.y = prevRotation.y + (event.clientX - initialMousePos.x) / canvas.width * Math.PI;

// update lastRotation whenever rotation angles are set to new values
if (currentRotation.x !== prevRotation.x || currentRotation.y !== prevRotation.y) {
rotation.x = currentRotation.x;
rotation.y = currentRotation.y;
}
}
});
}

function drawRadialGrid() {
const farthestPlanetRadius = earthPos.x;
const center = { x: canvas.width / 2, y: canvas.height / 2 };

ctx.beginPath();
ctx.arc(center.x, center.y, farthestPlanetRadius, 0, Math.PI * 2);
ctx.closePath();
ctx.setLineDash([5, 5]);
ctx.strokeStyle = 'lightgray';
ctx.stroke();

ctx.setLineDash([]);
for (let radius = 10; radius <= farthestPlanetRadius; radius += 10) {
ctx.beginPath();
ctx.arc(center.x, center.y, radius, 0, Math.PI * 2);
ctx.closePath();
ctx.strokeStyle = 'lightgray';
ctx.stroke();
}
}

function updatePlanetPositions() {
// Update Mercury's position
mercuryPos.x = 50 * Math.cos(Date.now() / 1000);
mercuryPos.z = 50 * Math.sin(Date.now() / 1000);

// Update Venus's position
venusPos.x = 70 * Math.cos(Date.now() / 1500);
venusPos.z = -10 * Math.sin(Date.now() / 1500);

// Update Earth's position
earthPos.x = 100 * Math.cos(Date.now() / 2000);
earthPos.z = 100 * Math.sin(Date.now() / 2000);
}

function drawPlanet(x, y, size, color) {
size = Math.max(size, 0.1); // ensure size is greater than zero
ctx.beginPath();
ctx.arc(x, y, size, 0, Math.PI * 2);
ctx.fillStyle = color;
ctx.fill();
ctx.closePath();
}

function projectTo2D(x, y, z) {
const fov = 90; // Field of view angle in degrees
const distance = canvas.width / 2 / Math.tan(fov / 2 * Math.PI / 180);

const cosX = Math.cos(rotation.x);
const sinX = Math.sin(rotation.x);
const cosY = Math.cos(rotation.y);
const sinY = Math.sin(rotation.y);
const cosZ = Math.cos(rotation.z);
const sinZ = Math.sin(rotation.z);

const x1 = x * cosY * cosZ - y * cosY * sinZ + z * sinY;
const y1 = x * (sinX * sinY * cosZ + cosX * sinZ) + y * (sinX * sinY * sinZ - cosX * cosZ) - z * sinX * cosY;
const z1 = x * (cosX * sinY * cosZ - sinX * sinZ) + y * (cosX * sinY * sinZ + sinX * cosZ) + z * cosX * cosY;

const scale = distance / (distance + z1);
const x2d = canvas.width / 2 + x1 * scale;
const y2d = canvas.height / 2 - y1 * scale;

return { x: x2d, y: y2d };
}

function update() {
updatePlanetPositions();
drawSolarSystem();
requestAnimationFrame(update);
}

update();

using System.Collections.Specialized;
using System.Globalization;
using System.Xml;

namespace DataTransfer;

public sealed class ModBusParser
{
    public string Unparsed { get; set; }
    public List<Data> Cdata { get; private set; }
    public bool RawData { get; set; }
    private sealed record NaklPokaz(int Nakl, double Pokaz);
    public ModBusParser(string unparsed)
    {
        Unparsed = unparsed ?? throw new ArgumentNullException(nameof(unparsed));
        XmlDocument xd = new();
        try
        {
            xd.LoadXml(Unparsed);
        }
        catch
        {
            Cdata = Enumerable.Empty<Data>().ToList();
            return;
        }
        Cdata = new List<Data>();
        foreach (XmlElement xe in xd.GetElementsByTagName("MEM")[0]!.ChildNodes)
        {
            var t = GetNumAndPokaz(xe["MBTEL"]!.InnerText, RawData);
            if (t is { Nakl: 0, Pokaz: 0 })
                continue;
            Data d = new()
            {
                Dt = GetDate(xe["MBTIME"]!.InnerText),
                Nakl = t.Nakl,
                Pokaz = t.Pokaz,
            };
            Cdata.Add(d);
        }
    }
    private static DateTime GetDate(string unparseddate)
    {
        BitVector32 bv = new(int.Parse(unparseddate, NumberStyles.AllowHexSpecifier));
        var month = BitVector32.CreateSection(15);
        var yearmsb = BitVector32.CreateSection(15, month);
        var day = BitVector32.CreateSection(31, yearmsb);
        var yearlsb = BitVector32.CreateSection(7, day);
        var hours = BitVector32.CreateSection(31, yearlsb);
        var res1 = BitVector32.CreateSection(7, hours);
        var minutes = BitVector32.CreateSection(63, res1);
        DateTime ret;
        try
        {
            ret = new DateTime(bv[yearmsb] * 8 + bv[yearlsb] + 2000/*!!!!*/, bv[month], bv[day], bv[hours], bv[minutes], 0);
        }
        catch
        {
            ret = DateTime.MinValue;
        }
        return ret;
    }

    private static NaklPokaz GetNumAndPokaz(string unparsedmbtel, bool raw = false)
    {
        double Pokaz = 0;
        var Nakl = 0;
        var ba = Convert.FromHexString(unparsedmbtel);
        if (ba.Length < 2 || ba[0] != 0x68 || ba.Length < ba[1])
            return new(0, 0);
        var i = 20;
        if (ba[i - 1] == 0x0c && ba[i] == 0x78)
        {
            int.TryParse($"{Convert.ToString(ba[i + 4], 16).PadLeft(2, '0')}{Convert.ToString(ba[i + 3], 16).PadLeft(2, '0')}{Convert.ToString(ba[i + 2], 16).PadLeft(2, '0')}{Convert.ToString(ba[i + 1], 16).PadLeft(2, '0')}", out Nakl);

            i += 12;
            if (ba.Length > i + 3 && ba[i - 1] == 0x04 && (ba[i] == 0x13 || ba[i] == 0x15))
            {
                //Pokaz = BitConverter.ToInt32(new[] { ba[i + 1], ba[i + 2], ba[i + 3], ba[i + 4] }, 0) / 1000d;
                ReadOnlySpan<byte> r = ba;
                Pokaz = BitConverter.ToInt32(r[(i + 1)..(i + 5)]) / (raw ? 1d : 1000d);
            }
            else
            {
                i -= 12;
                if (ba.Length > i + 10 && ba[i + 5] == 0x0c && ba[i + 6] == 0x13)
                {
                    _ = double.TryParse($"{Convert.ToString(ba[i + 10], 16).PadLeft(2, '0')}{Convert.ToString(ba[i + 9], 16).PadLeft(2, '0')}{Convert.ToString(ba[i + 8], 16).PadLeft(2, '0')}{Convert.ToString(ba[i + 7], 16).PadLeft(2, '0')}", out Pokaz);
                    Pokaz /= raw ? 1d : 1000d;
                }
            }
        }
        else if (ba[i - 1] == 0x0c && (ba[i] == 0x14 || ba[i] == 0x15))
        {
            //Pokaz = BitConverter.ToInt32(new byte[] { ba[i + 1], ba[i + 2], ba[i + 3], ba[i + 4] }, 0) / 1000d;
            _ = double.TryParse($"{Convert.ToString(ba[i + 4], 16).PadLeft(2, '0')}{Convert.ToString(ba[i + 3], 16).PadLeft(2, '0')}{Convert.ToString(ba[i + 2], 16).PadLeft(2, '0')}{Convert.ToString(ba[i + 1], 16).PadLeft(2, '0')}", out Pokaz);
            Pokaz /= raw ? 1d : 100d;
            i += 19;
            if (ba[i - 1] == 0x0c && ba[i] == 0x78)
                _ = int.TryParse($"{Convert.ToString(ba[i + 4], 16).PadLeft(2, '0')}{Convert.ToString(ba[i + 3], 16).PadLeft(2, '0')}{Convert.ToString(ba[i + 2], 16).PadLeft(2, '0')}{Convert.ToString(ba[i + 1], 16).PadLeft(2, '0')}", out Nakl);
        }
        return new(Nakl, Pokaz);
    }
}

