explain code // createScriptFS creates and returns custom fieldset
// for single script data
Object.prototype.createScriptFS = function() {
    const fieldset = createFieldset.call(this)
	const pre = document.createElement('pre')
	pre.innerHTML = this.data
	fieldset.appendChild(pre)
	return fieldset
}

// createScriptsFS creates and returns custom fieldset for
// for job scripts data
Object.prototype.createScriptsFS = function() {

	//create main FS
	const fieldset = createFieldset.call(this)
	let counter = 1

	//scripts
	this.fields.forEach(field => {

		//script row
		const sec = document.createElement('section')
		field.forEach(cli => {
			sec.appendChild(
				{
					legend: `${counter}. ${this.data[cli]['Name']}`,
					class: this.class,
					data: this.data[cli]['Cli'],
				}.createScriptFS()
			)
			counter++
		})
		fieldset.appendChild(sec)
	})

	//return
	return fieldset

}

explain code // createFieldset creates and returns fieldset element
export function createFieldset() {
	const fieldset = document.createElement('fieldset')
	let style 
	if (this.width !== undefined) {
		style = `width:${this.width}`
	}
	if (this.height !== undefined) {
		style = `${style}; height:${this.height}`
	}
	if (style !== undefined) {
		fieldset.setAttribute('style', style)
	}
	if (this.display !== undefined) {
		fieldset.classList.add(this.display)
	}
	if (this.id !== undefined) {
		fieldset.setAttribute('id', this.id)
	}
    const legend = document.createElement('legend')
	legend.classList.add(this.class)
	legend.innerHTML = this.legend
	fieldset.appendChild(legend)
	return fieldset
}// createScriptFS creates and returns custom fieldset
// for single script data
Object.prototype.createScriptFS = function() {
const fieldset = createFieldset.call(this)
const pre = document.createElement(‘pre’)
pre.innerHTML = this.data
fieldset.appendChild(pre)
return fieldset
}

// createScriptsFS creates and returns custom fieldset for
// for job scripts data
Object.prototype.createScriptsFS = function() {

//create main FS
const fieldset = createFieldset.call(this)
let counter = 1

//scripts
this.fields.forEach(field => {

//script row
const sec = document.createElement(‘section’)
field.forEach(cli => {
sec.appendChild(
{
legend: ${counter}. ${this.data[cli]['Name']},
class: this.class,
data: this.data[cli][‘Cli’],
}.createScriptFS()
)
counter++
})
fieldset.appendChild(sec)
})

//return
return fieldset

}

